def seal():
 pts=[]
 for i in range(241):
  a=2*math.pi*i/240-math.pi/2;r=46+3.7*math.cos(12*(a+math.pi/2));pts.append((64+r*math.cos(a),64+r*math.sin(a)))
 return 'M'+' L'.join(f'{x:.3f},{y:.3f}' for x,y in pts)+' Z'
